mapper.select:
SELECT DATE_FORMAT(T.UPTIME, '%Y') AS YEAR, T.EQUIPTCATEGORY, SUM(T.AMOUNT) AS AMOUNT FROM T_CORE_EQUIPT_USAGE_RECORD T WHERE T.UPTIME BETWEEN STR_TO_DATE (#{startYear}, '%Y-%m-%d %H:%i:%s') AND STR_TO_DATE (#{endYear}, '%Y-%m-%d %H:%i:%s')
AND T.EQUIPTCATEGORY = #{equiptCategory}
GROUP BY T.EQUIPTCATEGORY, DATE_FORMAT(T.UPTIME, '%Y')
